import {copyHTML,copyRaw} from './site-copy.js';
import {backend} from './backend.js';
import {escape as e} from './store.js';
import {builtinResources,legacyTables,applyLibraryOverrides,loadLibraryOverrides,libraryOverrideError} from './library-overrides.js';
const kinds={get "materials"(){return copyRaw("sample-editor.fd10a146e962");},get "lectureNotes"(){return copyRaw("sample-editor.b2b5202e7477");},get "lectures"(){return copyRaw("sample-editor.95f7caf5f942");},get "cases"(){return copyRaw("sample-editor.2249bd503ec4");},get "flashcards"(){return copyRaw("sample-editor.eac4b70868b6");},get "quizSets"(){return copyRaw("sample-editor.dd0acd7417ae");},get "quizQuestions"(){return copyRaw("sample-editor.f5f777044b10");}};
let items={},kind='quizSets',errors=[],loading=false,epoch=0;
export function resetSampleEditor(){epoch++;items={};errors=[];loading=false;}
export async function loadSamples(ui){const stamp=++epoch,owner=backend.user()?.id;loading=true;ui.render();try{if(!await backend.isAdmin())throw new Error(copyRaw("sample-editor.0e83b057c6d5"));await loadLibraryOverrides();const result=await Promise.all(Object.keys(kinds).map(async key=>{let legacy=[];if(legacyTables[key])try{legacy=await backend.read(legacyTables[key]);if(!Array.isArray(legacy))legacy=[];}catch{errors.push(kinds[key]);}return [key,[...builtinResources(key),...legacy.map(row=>({...row,title:row.title||row.name,name:row.name||row.title,body:row.body||row.content||row.summary||'',subject:row.subject||row.course||'General',quiz_set_id:row.quiz_set_id||row.quiz_id,library_source:'legacy'}))]];}));if(stamp===epoch&&backend.user()?.id===owner)items=Object.fromEntries(result);}catch(err){errors=[err.message];}finally{if(stamp===epoch){loading=false;ui.render();}}}
export function samplesScreen(){const rows=applyLibraryOverrides(kind,items[kind]||[],{includeHidden:true});return `<section class="card"><div class="card-head"><h2>${copyHTML("sample-editor.74f583d7e970")}</h2><button class="btn" id="samples-refresh">${copyHTML("sample-editor.0953524e2307")}</button></div><p class="muted">${copyHTML("sample-editor.b9fc4391ce1a")}</p>${libraryOverrideError()?`<p role="alert">${e(libraryOverrideError())} ${copyHTML("sample-editor.3f8915c3428d")}</p>`:''}<label for="samples-kind">${copyHTML("sample-editor.6f51cb040320")}</label><select id="samples-kind">${Object.entries(kinds).map(([key,label])=>`<option value="${key}" ${kind===key?'selected':''}>${label}</option>`).join('')}</select>${loading?`<p role="status">${copyHTML("sample-editor.8c0cf03ca49a")}</p>`:rows.map((row,index)=>`<div class="row"><div class="row-copy"><strong>${e(row.title||row.name||row.front||row.question)}</strong><small>${e(row.subject||'')} · ${row.library_source==='builtin'?copyRaw("sample-editor.34193878be1a"):copyRaw("sample-editor.0c46e5ffd793")}${row.library_hidden?' · Hidden':''}</small></div><button class="btn" data-sample-edit="${index}">${copyHTML("sample-editor.464c4ffd019e")}</button><button class="btn" data-sample-hide="${index}">${row.library_hidden?copyRaw("sample-editor.0df6f1cad36c"):copyRaw("sample-editor.ac20a57bfde0")}</button><button class="btn" data-sample-reset="${index}">${copyHTML("sample-editor.7b591d09309b")}</button></div>`).join('')||`<p class="muted">${copyHTML("sample-editor.762112dc32ec")}</p>`}${errors.length?`<p class="muted">${copyHTML("sample-editor.cd36085c757a")}${e([...new Set(errors)].join(', '))}${copyHTML("sample-editor.3f5556edeb14")}</p>`:''}</section>`;}
export function bindSamples(ui){const refresh=document.querySelector('#samples-refresh');if(!refresh)return;refresh.onclick=()=>{errors=[];loadSamples(ui);};document.querySelector('#samples-kind').onchange=event=>{kind=event.target.value;ui.render();};const rows=applyLibraryOverrides(kind,items[kind]||[],{includeHidden:true});
 for(const button of document.querySelectorAll('[data-sample-edit]'))button.onclick=()=>edit(rows[Number(button.dataset.sampleEdit)],ui);
 for(const button of document.querySelectorAll('[data-sample-hide]'))button.onclick=async()=>{button.disabled=true;try{const row=rows[Number(button.dataset.sampleHide)];await backend.saveLibraryOverride({kind,source:row.library_source,source_id:row.id,content:contentOf(row),hidden:!row.library_hidden});await ui.reload();await loadSamples(ui);ui.toast(copyRaw("sample-editor.342ea99d2c8a"));}catch(err){ui.toast(err.message);button.disabled=false;}};
 for(const button of document.querySelectorAll('[data-sample-reset]'))button.onclick=()=>{const row=rows[Number(button.dataset.sampleReset)];ui.modal(copyRaw("sample-editor.a8db9218a3da"),`<p>${copyHTML("sample-editor.bb11c4a69834")} ${e(row.title||row.name||row.question||row.front)} ${copyHTML("sample-editor.69d30a52c131")}</p><button class="btn" id="sample-confirm-reset">${copyHTML("sample-editor.31d9ca80e7ae")}</button>`);document.querySelector('#sample-confirm-reset').onclick=async event=>{event.target.disabled=true;try{await backend.resetLibraryOverride(kind,row.library_source,row.id);document.querySelector('#dialog').close();await ui.reload();await loadSamples(ui);}catch(err){ui.toast(err.message);event.target.disabled=false;}};};
}
const keys=['title','name','subject','description','body','front','back','question','options','correct_index','explanation','time_minutes','difficulty','citation','url','quiz_set_id','type'];
function contentOf(row){return Object.fromEntries(keys.filter(key=>row[key]!==undefined).map(key=>[key,row[key]]));}
function edit(row,ui){if(!row)return;const editingKind=kind;
 const field=(key,label,area=false)=>`<label for="sample-${key}">${label}</label><${area?'textarea':'input'} id="sample-${key}" name="${key}" ${area?'rows="6"':'value="'+e(row[key]??'')+'"'} maxlength="${area?100000:4000}">${area?e(row[key]??'')+'</textarea>':''}`;
 let fields=field('subject',copyRaw("sample-editor.68971283841a"));
 if(kind==='quizQuestions'){const sets=applyLibraryOverrides('quizSets',items.quizSets||[],{includeHidden:true});fields+=`<label for="sample-quiz-set">${copyHTML("sample-editor.e1bf4b3f3d18")}</label><select name="quiz_set_id" id="sample-quiz-set">${sets.map(set=>`<option value="${e(set.id)}" ${String(set.id)===String(row.quiz_set_id)?'selected':''}>${e(set.name)} (${set.library_source})</option>`).join('')}</select>`+field('question',copyRaw("sample-editor.289aff12b042"),true)+[0,1,2,3].map(index=>`<label for="sample-option-${index}">${copyHTML("sample-editor.45aaacba7ea1")} ${'ABCD'[index]}</label><input id="sample-option-${index}" name="option${index}" required value="${e(row.options?.[index]||'')}" maxlength="2000">`).join('')+`<label for="sample-correct">${copyHTML("sample-editor.fb019d338b43")}</label><select name="correct_index" id="sample-correct">${[0,1,2,3].map(index=>`<option value="${index}" ${Number(row.correct_index)===index?'selected':''}>${'ABCD'[index]}</option>`).join('')}</select>`+field('explanation',copyRaw("sample-editor.16ee4625bce9"),true);}
 else if(kind==='flashcards')fields+=field('front',copyRaw("sample-editor.289aff12b042"),true)+field('back',copyRaw("sample-editor.b2a3aa602762"),true);
 else{fields+=field(kind==='quizSets'?'name':'title',copyRaw("sample-editor.7e8cd2056da7"))+field('description',copyRaw("sample-editor.526e0087cc3f"),true);if(kind==='quizSets')fields+=`<label for="sample-time">${copyHTML("sample-editor.0f8f608aa012")}</label><input id="sample-time" type="number" name="time_minutes" min="1" max="180" required value="${Number(row.time_minutes)||10}">`+field('difficulty',copyRaw("sample-editor.be44133ed57f"));else if(kind!=='lectures')fields+=field('body',copyRaw("sample-editor.0a6a90f5a4ec"),true)+field('url',copyRaw("sample-editor.553c123e7390"));if(kind==='cases')fields+=field('citation',copyRaw("sample-editor.2955789aa4f8"));}
 ui.modal(copyRaw("sample-editor.4f6911a81930"),`<form id="sample-edit-form">${fields}<p role="status" id="sample-status"></p><button class="btn primary">${copyHTML("sample-editor.c236d1fa3597")}</button></form>`);
 document.querySelector('#sample-edit-form').onsubmit=async event=>{event.preventDefault();const form=event.target,status=form.querySelector('#sample-status'),button=form.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(editingKind==='quizQuestions'){data.options=[0,1,2,3].map(i=>data['option'+i].trim());for(let i=0;i<4;i++)delete data['option'+i];data.correct_index=Number(data.correct_index);if(!data.question.trim()||!data.quiz_set_id||data.options.some(value=>!value))throw new Error(copyRaw("sample-editor.bded241ddab5"));}if(editingKind==='quizSets'){data.time_minutes=Number(data.time_minutes);if(!data.name.trim()||data.time_minutes<1||data.time_minutes>180)throw new Error(copyRaw("sample-editor.8966885eeabe"));}if(data.url&&!/^https?:\/\//i.test(data.url))throw new Error(copyRaw("sample-editor.0cd036141c98"));await backend.saveLibraryOverride({kind:editingKind,source:row.library_source,source_id:row.id,content:{...contentOf(row),...data},hidden:row.library_hidden===true});document.querySelector('#dialog').close();await ui.reload();await loadSamples(ui);ui.toast(copyRaw("sample-editor.d2908708428b"));}catch(err){status.textContent=err.message;button.disabled=false;}};
}
